/** Unique characteristic of an asset. Supported values: - `ptp_no_exception`: Asset is a Publicly Traded Partnership (PTP) without a qualified notice; non-U.S. customers may incur 10% withholding on gross proceeds as per IRS guidance, and are blocked from being purchased by default. - `ptp_with_exception`: Users can open positions in these PTPs without general restrictions. - `ipo`: Accepting limit orders only before the stock begins trading on the secondary market. - `has_options`: The underlying equity has listed options available on the platform. Note: if the equity had inactive/expired contracts in the past, this will still show up. - `options_late_close`: Indicates the underlying asset's options contracts close at 4:15pm ET instead of the standard 4:00pm ET. - `fractional_eh_enabled`: Indicates the asset accepts fractional orders during extended hours sessions (pre-market, post-market, and overnight if enabled). - `overnight_tradable`: Asset is eligible for overnight (24x5) trading in supported venues on the platform. - `overnight_halted`: Asset is eligible for overnight trading but is currently halted/blocked for overnight sessions due to risk, corporate action, compliance, or venue constraints. */
export const AssetAttributeSchema = Z.enum([
  "ptp_no_exception",
  "ptp_with_exception",
  "ipo",
  "has_options",
  "options_late_close",
  "fractional_eh_enabled",
  "overnight_tradable",
  "overnight_halted",
]);
export type AssetAttribute = Z.output<typeof AssetAttributeSchema>;

/** This represents the category to which the asset belongs to. It serves to identify the nature of the financial instrument, with options including "us_equity" for U.S. equities, "us_option" for U.S. options, "crypto" for cryptocurrencies, and "ipo" for IPO indications of interest/orders. This `asset_class: ipo` value is distinct from the assets API `attributes: ["ipo"]` flag. */
export const AssetClassSchema = Z.enum([
  "us_equity",
  "us_option",
  "crypto",
  "crypto_perp",
  "treasury",
  "corporate",
  "global_equity",
  "us_index",
  "us_equity_chain",
  "ipo",
]);
export type AssetClass = Z.output<typeof AssetClassSchema>;

/** Represents the current exchanges Alpaca supports. List is currently: */
export const ExchangeSchema = Z.enum(["AMEX", "ARCA", "BATS", "NYSE", "NASDAQ", "NYSEARCA", "OTC", "CRYPTO"]);
export type Exchange = Z.output<typeof ExchangeSchema>;

/** The assets API serves as the master list of assets available for trade and data consumption from Alpaca. Assets are sorted by asset class, exchange and symbol. Some assets are only available for data consumption via Polygon, and are not tradable with Alpaca. These assets will be marked with the flag tradable=false. */
export const AssetsSchema = Z.object({
  attributes: Z.array(AssetAttributeSchema).optional(),
  /** Borrow status for US equity assets. This field is omitted for non-US-equity assets. */
  borrow_status: Z.enum(["easy_to_borrow", "hard_to_borrow"]).optional(),
  class: AssetClassSchema,
  /** The CUSIP identifier for the asset (US Equities only). To request a specific CUSIP, please reach out to Alpaca support. */
  cusip: Z.string().nullable().optional(),
  exchange: ExchangeSchema,
  /** Asset is fractionable or not */
  fractionable: Z.boolean(),
  /** Asset ID */
  id: Z.string(),
  /** **deprecated**: Please use margin_requirement_long or margin_requirement_short instead. Note that these fields are of type string. Shows the margin requirement percentage for the asset (equities only). */
  maintenance_margin_requirement: Z.number().optional(),
  /** The margin requirement percentage for the asset's long positions (equities only), encoded as a decimal string. */
  margin_requirement_long: Z.string().optional(),
  /** The margin requirement percentage for the asset's short positions (equities only), encoded as a decimal string. */
  margin_requirement_short: Z.string().optional(),
  /** Asset is marginable or not */
  marginable: Z.boolean(),
  /** Minimum order size. Field available for crypto only. */
  min_order_size: Z.string().optional(),
  /** Amount a trade quantity can be incremented by. Field available for crypto only. */
  min_trade_increment: Z.string().optional(),
  /** The official name of the asset */
  name: Z.string(),
  /** Amount the price can be incremented by. Field available for crypto only. */
  price_increment: Z.string().optional(),
  /** Asset is shortable or not */
  shortable: Z.boolean(),
  /** active or inactive */
  status: Z.enum(["active", "inactive"]),
  /** The symbol of the asset */
  symbol: Z.string(),
  /** Asset is tradable on Alpaca or not */
  tradable: Z.boolean(),
});
export type Assets = Z.output<typeof AssetsSchema>;

