/** The order classes supported by Alpaca vary based on the order's security type. The following provides a comprehensive breakdown of the supported order classes for each category: - Equity trading: simple (or ""), oco, oto, bracket. - Options trading: - simple (or "") - mleg (required for multi-leg complex option strategies) - Crypto trading: simple (or ""). */
export const OrderClassSchema = Z.enum(["simple", "bracket", "oco", "oto", "mleg", ""]);
export type OrderClass = Z.output<typeof OrderClassSchema>;

/** The Time-In-Force values supported by Alpaca vary based on the order's security type. Here is a breakdown of the supported TIFs for each specific security type: - Equity trading: day, gtc, opg, cls, ioc, fok. - Options trading: day, gtc. - Crypto trading: gtc, ioc. */
export const TimeInForceSchema = Z.enum(["day", "gtc", "opg", "cls", "ioc", "fok"]);
export type TimeInForce = Z.output<typeof TimeInForceSchema>;

/** The order types supported by Alpaca vary based on the order's security type. The following provides a comprehensive breakdown of the supported order types for each category: - Equity trading: market, limit, stop, stop_limit, trailing_stop. - Options trading: market, limit, stop, stop_limit. - Multileg Options trading: market, limit. - Crypto trading: market, limit, stop_limit. */
export const OrderTypeSchema = Z.enum(["market", "limit", "stop", "stop_limit", "trailing_stop"]);
export type OrderType = Z.output<typeof OrderTypeSchema>;

/** Represents a request to create an order. */
export const CreateOrderRequestSchema = Z.object({
  advanced_instructions: AdvancedInstructionsSchema.optional(),
  /** A unique identifier for the order. Automatically generated if not sent. (<= 128 characters) */
  client_order_id: Z.string().optional(),
  /** (default) false. If true, order will be eligible for execution in the pre-market, after-hours, and overnight sessions. Only works with type `limit` and time_in_force set to either `day` or `gtc` */
  extended_hours: Z.boolean().optional(),
  /** list of order legs (<= 4) */
  legs: Z.array(MLegOrderLegSchema).optional(),
  /** Required if type is `limit` or `stop_limit`. In case of `mleg`, the limit_price parameter is expressed with the following notation: - A positive value indicates a debit, representing a cost or payment to be made. - A negative value signifies a credit, reflecting an amount to be received. */
  limit_price: Z.string().optional(),
  /** dollar amount to trade. Cannot work with `qty`. Can only work for market order types and day for time in force. */
  notional: Z.string().optional(),
  order_class: OrderClassSchema.optional(),
  position_intent: PositionIntentSchema.optional(),
  /** number of shares to trade. Can be fractionable for only market and day order types. Required for `mleg` order class, represents the number of units to trade of this strategy. */
  qty: Z.string().optional(),
  side: OrderSideSchema.optional(),
  /** Takes in string/number values for stop_price and limit_price */
  stop_loss: Z.object({
    limit_price: Z.string().optional(),
    stop_price: Z.string().optional(),
  }).optional(),
  /** required if type is `stop` or `stop_limit` */
  stop_price: Z.string().optional(),
  /** symbol, asset ID, or currency pair to identify the asset to trade, required for all order classes except for `mleg`. */
  symbol: Z.string().optional(),
  /** Takes in a string/number value for limit_price */
  take_profit: Z.object({
    limit_price: Z.string().optional(),
  }).optional(),
  time_in_force: TimeInForceSchema,
  /** this or `trail_price` is required if type is `trailing_stop` */
  trail_percent: Z.string().optional(),
  /** this or `trail_percent` is required if type is `trailing_stop` */
  trail_price: Z.string().optional(),
  type: OrderTypeSchema,
});
export type CreateOrderRequest = Z.output<typeof CreateOrderRequestSchema>;

