export const OptionDeliverableSchema = Z.object({
  /** Cost allocation percentage of the deliverable. This is used to determine the cost basis of the equity shares received from the exercise, specially for non-standard contracts with multiple deliverables. */
  allocation_percentage: Z.string(),
  /** The deliverable amount. For cash deliverables, this is the cash amount. For standard contract, this is always 100. When deliverable settlement is delayed and the amount is not yet determined, this value is "0" and delayed_settlement is true. */
  amount: Z.string(),
  /** Unique identifier of the deliverable asset. For standard contracts, this is equivalent to underlying_asset_id of the contracts. This field is not returned for cash deliverables. */
  asset_id: Z.string().optional(),
  /** If true, the settlement of the deliverable will be delayed. For instance, in the event of a contract with a delayed deliverable being exercised, both the availability of the deliverable and its settlement may be postponed beyond the typical timeframe. */
  delayed_settlement: Z.boolean(),
  /** Indicates the settlement method that will be used: - **BTOB**: Broker to Broker - **CADF**: Cash Difference - **CAFX**: Cash Fixed - **CCC**: Correspondent Clearing Corp */
  settlement_method: Z.enum(["BTOB", "CADF", "CAFX", "CCC"]),
  /** Indicates when the deliverable will be settled if the contract is exercised/assigned. */
  settlement_type: Z.enum(["T+0", "T+1", "T+2", "T+3", "T+4", "T+5"]),
  /** Symbol of the deliverable. For standard contracts, this is equivalent to the underlying symbol of the contract. */
  symbol: Z.string(),
  /** Type of deliverable, indicating whether it's cash or equity. For standard contracts, it is always "equity". */
  type: Z.enum(["cash", "equity"]),
});
export type OptionDeliverable = Z.output<typeof OptionDeliverableSchema>;

/** The style of the option contract. */
export const OptionContractStyleSchema = Z.enum(["american", "european"]);
export type OptionContractStyle = Z.output<typeof OptionContractStyleSchema>;

/** The type of the option contract. */
export const OptionContractTypeSchema = Z.enum(["call", "put"]);
export type OptionContractType = Z.output<typeof OptionContractTypeSchema>;

export const OptionContractSchema = Z.object({
  /** The close price of the option contract. */
  close_price: Z.string().optional(),
  /** The date of the close price data. */
  close_price_date: Z.iso.date().optional(),
  /** Represents the deliverables tied to the option contract. While standard contracts entail a single deliverable, non-standard ones can encompass multiple deliverables, each potentially customized with distinct parameters. This array is included in the list contracts response only if the query parameter show_deliverables=true is provided. */
  deliverables: Z.array(OptionDeliverableSchema).optional(),
  /** The expiration date of the option contract. */
  expiration_date: Z.iso.date(),
  /** The unique identifier of the option contract. */
  id: Z.string(),
  /** The multiplier of the option contract is crucial for calculating both the trade premium and the extended strike price. In standard contracts, the multiplier is always set to 100. For instance, if a contract is traded at $1.50 and the multiplier is 100, the total amount debited when buying the contract would be $150.00. Similarly, when exercising a call contract, the total cost will be equal to the strike price times the multiplier. */
  multiplier: Z.string(),
  /** The name of the option contract. */
  name: Z.string(),
  /** The open interest of the option contract. */
  open_interest: Z.string().optional(),
  /** The date of the open interest data. */
  open_interest_date: Z.iso.date().optional(),
  /** The ppind (Penny Program Indicator) field indicates whether an option contract is eligible for penny price increments, with `true` meaning it is part of the Penny Program and `false` meaning it is not. */
  ppind: Z.boolean(),
  /** The root symbol of the option contract. */
  root_symbol: Z.string().optional(),
  /** Represents the number of underlying shares to be delivered in case the contract is exercised/assigned. For standard contracts, this is always 100. This field should **not** be used as a multiplier, specially for non-standard contracts. */
  size: Z.string(),
  /** The status of the option contract. */
  status: Z.enum(["active", "inactive"]),
  /** The strike price of the option contract. */
  strike_price: Z.string(),
  style: OptionContractStyleSchema,
  /** The symbol representing the option contract. */
  symbol: Z.string(),
  /** Indicates whether the option contract is tradable. */
  tradable: Z.boolean(),
  type: OptionContractTypeSchema,
  /** The unique identifier of the underlying asset. */
  underlying_asset_id: Z.string(),
  /** The underlying symbol of the option contract. */
  underlying_symbol: Z.string(),
});
export type OptionContract = Z.output<typeof OptionContractSchema>;

