export const MicSchema = Z.string();
export type Mic = Z.output<typeof MicSchema>;

/** The full name of the market. */
export const MarketNameSchema = Z.string();
export type MarketName = Z.output<typeof MarketNameSchema>;

/** The timezone of the market. */
export const MarketTimezoneSchema = Z.string();
export type MarketTimezone = Z.output<typeof MarketTimezoneSchema>;

/** A market. */
export const PublicMarketSchema = Z.object({
  acronym: MarketAcronymSchema,
  bic: BicSchema.optional(),
  mic: MicSchema.optional(),
  name: MarketNameSchema,
  timezone: MarketTimezoneSchema,
});
export type PublicMarket = Z.output<typeof PublicMarketSchema>;

export const PhaseSchema = Z.enum(["closed", "pre", "core", "lunch", "post"]);
export type Phase = Z.output<typeof PhaseSchema>;

export const ClockSchema = Z.object({
  /** Whether the clock is on a market day. */
  is_market_day: Z.boolean(),
  market: PublicMarketSchema,
  /** Next market close timestamp */
  next_market_close: Z.iso.datetime({ offset: true }),
  /** Next market open timestamp */
  next_market_open: Z.iso.datetime({ offset: true }),
  phase: PhaseSchema,
  /** The end of the current phase. */
  phase_until: Z.iso.datetime({ offset: true }),
  /** The time on the clock. */
  timestamp: Z.iso.datetime({ offset: true }),
});
export type Clock = Z.output<typeof ClockSchema>;

/** Clock response. */
export const ClockRespSchema = Z.object({
  clocks: Z.array(ClockSchema),
});
export type ClockResp = Z.output<typeof ClockRespSchema>;

/** A calendar day. */
export const LegacyCalendarDaySchema = Z.object({
  /** The time the market closes at on this date in HH:MM format. */
  close: Z.string(),
  /** Date string in YYYY-MM-DD format. */
  date: Z.iso.date(),
  /** The time the market opens at on this date in HH:MM format. */
  open: Z.string(),
  /** The time the session closes at on this date in HHMM format. */
  session_close: Z.string(),
  /** The time the session opens at on this date in HHMM format. */
  session_open: Z.string(),
  /** Date string in YYYY-MM-DD format. Representing the settlement date for the trade date. */
  settlement_date: Z.iso.date(),
});
export type LegacyCalendarDay = Z.output<typeof LegacyCalendarDaySchema>;

export const LegacyClockSchema = Z.object({
  /** Whether or not the market is open. */
  is_open: Z.boolean(),
  /** Next market close timestamp. */
  next_close: Z.iso.datetime({ offset: true }),
  /** Next market open timestamp. */
  next_open: Z.iso.datetime({ offset: true }),
  /** Current timestamp. */
  timestamp: Z.iso.datetime({ offset: true }),
});
export type LegacyClock = Z.output<typeof LegacyClockSchema>;

export const LegacyPublicCalendarRespSchema = Z.array(LegacyCalendarDaySchema);
export type LegacyPublicCalendarResp = Z.output<typeof LegacyPublicCalendarRespSchema>;

/** The market identifier (MIC, BIC, or acronym). */
export const MarketSchema = Z.enum([
  "BMO",
  "BNYM",
  "BOATS",
  "CEUX",
  "CHIX",
  "HKEX",
  "IEX",
  "IEXG",
  "ISE",
  "LSE",
  "MTA",
  "MTAA",
  "NASDAQ",
  "NYSE",
  "OCEA",
  "OPRA",
  "OTC",
  "OTCM",
  "SIFMA",
  "TADAWUL",
  "XAMS",
  "XBRU",
  "XDUB",
  "XETR",
  "XETRA",
  "XHKG",
  "XLIS",
  "XLON",
  "XNAS",
  "XNYS",
  "XPAR",
  "XSAU",
]);
export type Market = Z.output<typeof MarketSchema>;

/** Calendar response. */
export const PublicCalendarRespSchema = Z.object({
  /** The market calendar. */
  calendar: Z.array(CalendarDaySchema),
  market: PublicMarketSchema,
});
export type PublicCalendarResp = Z.output<typeof PublicCalendarRespSchema>;
